class TransferSelection(private val activity:MainActivity,private val rows:List<TransferEntry>,private val importing:Boolean,private val overwrite:Boolean=false,private val operationTitle:String?=null,private val completionLabel:String?=null,private val commit:(List<TimelineEvent>)->Unit){private val selected=BooleanArray(rows.size){rows[it].defaultSelected};private val dialog=Dialog(activity);private val count=activity.label("",13f);private val adapter=object:BaseAdapter(){override fun getCount():Int=rows.size;override fun getItem(position:Int):Any=rows[position];override fun getItemId(position:Int):Long=position.toLong();override fun getView(position:Int,convertView:View?,parent:ViewGroup):View{val row=rows[position];val wrapper=(convertView as? LinearLayout)?:activity.row().apply{setPadding(activity.dp(3),activity.dp(2),activity.dp(3),activity.dp(2));val check=CheckBox(activity).apply{buttonTintList=ColorStateList.valueOf(RED);setTextColor(RED)};add(check,activity.dp(48),activity.dp(62));val info=activity.column();val name=activity.label("",15f).apply{setSingleLine(true);ellipsize=TextUtils.TruncateAt.END};val sub=activity.label("",11f).apply{setSingleLine(true);ellipsize=TextUtils.TruncateAt.END};info.add(name,-1,activity.dp(32));info.add(sub,-1,activity.dp(30));add(info,0,activity.dp(62),1f)};val cb=wrapper.getChildAt(0) as CheckBox;val info=wrapper.getChildAt(1) as LinearLayout;val text=info.getChildAt(0) as TextView;val sub=info.getChildAt(1) as TextView;text.text="${position+1}. ${row.title}";sub.text="${row.detail} · ${row.status}";cb.setOnCheckedChangeListener(null);cb.isEnabled=row.event!=null;cb.isChecked=selected[position];cb.setOnCheckedChangeListener{_,value->if(row.event!=null){selected[position]=value;updateCount()}};wrapper.setOnClickListener{if(row.event!=null){selected[position]=!selected[position];cb.isChecked=selected[position];updateCount()}};return wrapper}};init{val outer=activity.column();outer.setPadding(activity.dp(10),activity.dp(6),activity.dp(10),activity.dp(8));val header=activity.row();header.add(activity.label(operationTitle?:if(overwrite)"OVERWRITE TIMELINE" else if(importing)"IMPORT EVENTS" else "EXPORT EVENTS",19f),0,activity.dp(48),1f);val close=Glyph(activity,"close");close.contentDescription="Cancel ${if(importing)"import" else "export"}";header.add(close,activity.dp(48),activity.dp(48));close.setOnClickListener{dialog.dismiss()};outer.add(header);outer.add(count,-1,activity.dp(38));val controls=activity.row();controls.add(activity.action("ALL"){change(0)},0,activity.dp(45),1f);controls.add(activity.action("NONE"){change(1)},0,activity.dp(45),1f);controls.add(activity.action("INVERSE"){change(2)},0,activity.dp(45),1f);outer.add(controls);if(overwrite)outer.add(activity.label("DANGER ZONE · Only checked events will survive. Unchecked existing events will be deleted.",12f),-1,activity.dp(60));val list=ListView(activity).apply{setBackgroundColor(BLACK);dividerHeight=activity.dp(1);setAdapter(this@TransferSelection.adapter);setChoiceMode(ListView.CHOICE_MODE_NONE)};outer.add(list,-1,(activity.resources.displayMetrics.heightPixels*(if(overwrite)0.48 else 0.58)).toInt());val done=activity.action(completionLabel?:if(overwrite)"REVIEW OVERWRITE" else if(importing)"IMPORT SELECTED" else "EXPORT SELECTED"){val chosen=rows.indices.filter{selected[it]&&rows[it].event!=null}.mapNotNull{rows[it].event};dialog.dismiss();commit(chosen)};done.contentDescription=if(overwrite)"Review replacement of timeline with checked events" else "${if(importing)"Import" else "Export"} checked events";outer.add(done,-1,activity.dp(54));dialog.setContentView(outer);dialog.window?.setBackgroundDrawableResource(android.R.color.black);updateCount()};private fun change(mode:Int){TransferSelectionRules.change(BooleanArray(rows.size){rows[it].event!=null},selected,mode);adapter.notifyDataSetChanged();updateCount()};private fun updateCount(){val n=selected.count{it};val invalid=rows.count{it.event==null};count.text="$n selected / ${rows.size} events${if(invalid>0)" · $invalid invalid (disabled)" else ""}"};fun show(){dialog.show();dialog.window?.setLayout((activity.resources.displayMetrics.widthPixels*0.98).toInt(),WindowManager.LayoutParams.WRAP_CONTENT)}}
